// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the admin address passed to initialize; the property should hold for any admin
    function testFuzz_property(address admin) public {
        // avoid zero address to keep domain wide but meaningful (initializer should accept any address though)
        // not strictly necessary but keeps things practical
        vm.assume(admin != address(0));

        bool okFirst;
        // first initialize should succeed
        try c.initialize(admin) {
            okFirst = true;
        } catch {
            okFirst = false;
        }

        // If first initialize itself reverts, then both reference and mutant would revert for this input
        // We only proceed to test the distinguishing behavior when first initialize succeeded
        if (!okFirst) {
            // assert that c.initialize reverted on first call (both implementations may revert in some edge cases)
            // single assertion at end: so return early to avoid additional asserts
            assertTrue(true);
            return;
        }

        // Now attempt a second initialize call; in the correct contract this must revert (already initialized).
        bool okSecond;
        try c.initialize(admin) {
            okSecond = true;
        } catch {
            okSecond = false;
        }

        // General rule: second initialize must revert => okSecond == false. The buggy mutant that fails to set
        // _initialized will allow the second initialize to succeed for some admin values, making okSecond == true.
        assertTrue(!okSecond);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: address attackerImplementation - if this address is a contract that implements
    // IERC1822Proxiable.proxiableUUID() returning the correct slot, upgradeToAndCall path in UUPS will
    // attempt to call proxiableUUID() on newImplementation. The initializer mutation affects initialized state
    // and thus the notDelegated/onlyProxy checks; we fuzz the attacker implementation address by deploying
    // a helper whose returned slot we can vary via the fuzzed boolean decideCorrectSlot.
    function testFuzz_property(bool returnCorrectSlot) public {
        // Deploy an implementation-like helper that returns either the correct slot or a bad slot
        ImplHelper impl = new ImplHelper(returnCorrectSlot);

        // First, initialize the contract (should succeed on both reference and mutant for admissible inputs)
        c.initialize(address(this));

        // Now attempt to call proxiableUUID() directly on c (not-delegated path) which requires the function
        // to be callable only when not delegated. The reference's notDelegated modifier checks address(this) == __self
        // which is always true when calling directly, so proxiableUUID() should return the IMPLEMENTATION_SLOT constant.
        // We capture that via try/catch and assertTrue on the obtained value equivalence.

        // Call c.proxiableUUID() and expect it to return the ERC1967 implementation slot value stringly: but we can
        // only observe success vs revert or the returned bytes32. We'll assert that calling proxiableUUID() does NOT revert
        // and returns the well-known slot (0x3608...bbbc). The mutated initializer changes initialization state which can
        // affect the authorization logic path in some contexts; for at least some input (when returnCorrectSlot==false)
        // the mutant will diverge. We make the property universal: reference always returns the ERC1967 slot; mutant may not.

        bytes32 slot;
        try c.proxiableUUID() returns (bytes32 s) {
            slot = s;
        } catch {
            slot = bytes32(0);
        }

        // The ERC1967 implementation slot constant from the contract source
        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

        // Single assertion: reference C always returns the expected slot when called directly after initialize;
        // the mutant (which fails to mark initialized) will cause this to differ for some inputs and thus fail this assertion.
        assertTrue(slot == expected);
    }
}

// Minimal helper that can stand in as an implementation and return either the correct proxiable UUID or a bad one
contract ImplHelper {
    bool public retCorrect;
    constructor(bool _retCorrect) { retCorrect = _retCorrect; }
    function proxiableUUID() external view returns (bytes32) {
        if (retCorrect) {
            return 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        } else {
            return bytes32(uint256(0x123456));
        }
    }
}

