pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the _accessControl address passed to initialize; the property is:
    // For every admissible _accessControl (any address), the first call to initialize must succeed
    // and any immediate second call to initialize must revert (cannot re-initialize).
    // The mutant that doesn't mark _initialized will allow the second call to succeed for some addresses.
    function testFuzz_property(address accessControl) public {
        // keep domain wide but avoid zero address? reference should accept any address, including zero.
        // We do not vm.assume to keep wide domain so fuzzer can find breaking inputs for mutant.

        // First initialize should succeed (either as top-level initializer or construction); call from EOA
        bool ok1;
        try c.initialize(accessControl) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // If first call failed, then the reference must have rejected — but reference should accept first initialize when uninitialized.
        // To keep the property universal for the reference, we require that the first call succeeded; otherwise skip assert by returning.
        if (!ok1) return;

        // Second initialize call: in the reference this MUST revert (cannot reinitialize). We observe success/failure.
        bool ok2;
        try c.initialize(accessControl) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // Assert that second call did NOT succeed. Reference: ok2 == false for ALL inputs; mutant: exists input where ok2 == true.
        assertTrue(!ok2);
    }
}

