pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the accessControl address passed to initialize
    function testFuzz_property(address accessControl) public {
        // keep domain wide but non-zero (accessControl can be zero too; allow it)
        // 1) First initialize should succeed on both reference and mutant (subject to access semantics),
        //    but we just call it as external actor (fuzzer-supplied address) by using vm.prank to emulate caller.
        vm.prank(accessControl);
        bool ok1;
        try c.initialize(accessControl) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        // If the first initialize reverted, then both reference and mutant must have reverted for that input
        // (we only assert a property when first initialize succeeded). We constrain to cases where first call succeeds.
        vm.assume(ok1);

        // 2) Attempt a second initialize call with the same parameter from the same caller.
        vm.prank(accessControl);
        bool ok2;
        try c.initialize(accessControl) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // GENERAL RULE (single assertion): For the correct contract, a second initialize must always revert (ok2 == false).
        // The mutant that doesn't set _initialized will sometimes allow ok2 == true; the fuzzer will find such inputs.
        assertTrue(!ok2);
    }
}

