pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the _accessControl address which is passed into initialize
    function testFuzz_property(address accessControl) public {
        // keep domain wide but non-zero to avoid trivial zero-address guards
        vm.assume(accessControl != address(0));

        bool firstSucceeds;
        bool secondSucceeds;

        // First initialize: should succeed on reference for any admissible input
        try c.initialize(accessControl) {
            firstSucceeds = true;
        } catch {
            firstSucceeds = false;
        }

        // Second initialize: reference ALWAYS reverts (cannot reinitialize), so secondSucceeds must be false
        try c.initialize(accessControl) {
            secondSucceeds = true;
        } catch {
            secondSucceeds = false;
        }

        // The universal property we assert: if the first initialize succeeded, then the second must fail.
        // This holds for the reference for ALL admissible inputs; the mutant (which does not mark initialized)
        // will allow some inputs where both succeed, causing this assertion to fail.
        assertTrue(!firstSucceeds || !secondSucceeds);
    }
}

