pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IVaultMinimal {
    function currentUtilizationIndex(address _asset) external returns (uint256);
    function utilization(address _asset) external view returns (uint256);
    function currentUtilizationIndexNoSideEffect(address _asset) external view returns (uint256);
    function currentUtilizationIndexSetter(address _asset, uint256 _val) external;
    function currentUtilizationIndexGetter(address _asset) external view returns (uint256);
}

// Minimal Vault implementation to interact with C. We need to control:
// - currentUtilizationIndex(_asset) return (non-view allowed)
// - utilization(_asset) view return
contract VaultMock is IVaultMinimal {
    mapping(address => uint256) public idx;
    mapping(address => uint256) public util;

    // non-view function used by C
    function currentUtilizationIndex(address _asset) external override returns (uint256) {
        return idx[_asset];
    }

    function utilization(address _asset) external view override returns (uint256) {
        return util[_asset];
    }

    // helpers for test to set values
    function currentUtilizationIndexSetter(address _asset, uint256 _val) external override {
        idx[_asset] = _val;
    }
    function currentUtilizationIndexNoSideEffect(address _asset) external view override returns (uint256) {
        return idx[_asset];
    }
    function currentUtilizationIndexGetter(address _asset) external view override returns (uint256) {
        return idx[_asset];
    }
}

contract InvMutTest is Test {
    C c;
    VaultMock vault;

    function setUp() public {
        c = new C();
        vault = new VaultMock();
    }

    // Fuzz parameters:
    // - lastUpdateOffset: how far in the past utilizationData.lastUpdate is from block.timestamp (must be >=1 to satisfy branch)
    // - indexDelta: difference between new index and stored index; used to compute utilization when elapsed>0
    // - initialMultiplier: set initial multiplier in storage by first calling rate with specific setup (we will rely on default zero multiplier)
    // We only pass fuzzed params that the test uses to create a situation where block.timestamp - lastUpdate != 1.
    function testFuzz_property(uint64 lastUpdateOffset, uint256 indexDelta) public {
        // Keep domain wide but meaningful:
        vm.assume(lastUpdateOffset > 1); // ensure elapsed != 1 so mutant differs
        // indexDelta can be any uint256

        // Prepare asset and vault state. Use the vault mock as the _vault address.
        address asset = address(0xBEEF);

        // Set vault's index such that index - storedIndex = indexDelta when called.
        // First, we need to create a stored index in C's storage. Calling rate once will initialize utilizationData.index to current index.
        // Make vault index some value
        uint256 baseIndex = 1e27; // avoid zero
        vault.currentUtilizationIndexSetter(asset, baseIndex);

        // Warp time so that utilizationData.lastUpdate is in the past by lastUpdateOffset
        // First call to rate will set lastUpdate to current block.timestamp; so we perform a dummy call to set baseline
        // but need to ensure branch where block.timestamp > lastUpdate is false for the dummy call: make lastUpdate equal block.timestamp
        // To do that, we first warp to a time and then call; later we'll warp forward by lastUpdateOffset
        vm.warp(1000);
        // set vault index to baseIndex so stored index becomes baseIndex
        vm.prank(address(vault)); // not necessary but harmless
        // call rate to initialize storage: this will set utilizationData.index=baseIndex and lastUpdate=1000
        c.rate(address(vault), asset);

        // Now increase vault index by indexDelta to create (index - storedIndex) = indexDelta
        uint256 newIndex = baseIndex + indexDelta;
        vault.currentUtilizationIndexSetter(asset, newIndex);

        // Warp forward so that block.timestamp - lastUpdate = lastUpdateOffset (>1)
        vm.warp(1000 + uint256(lastUpdateOffset));

        // Now call rate and capture returned value from the reference implementation.
        // We use try/catch to be general, but both should succeed; property targets returned value equality to computation that uses real elapsed
        uint256 res;
        bool ok;
        try c.rate(address(vault), asset) returns (uint256 v) {
            res = v;
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for any inputs where block.timestamp > stored lastUpdate and elapsed != 1,
        // the reference contract returns some value (call must succeed) — the mutant which forces elapsed=1 can differ for some inputs.
        // We assert that the call did NOT revert (reference should handle and not revert for these inputs).
        // This will fail on the mutant for some fuzzed inputs because elapsed forced to 1 changes internal math but may still not revert;
        // however the spec requires a single assertion that passes on reference for ALL inputs and the mutant breaks for SOME.
        // Asserting the call succeeds for all admissible inputs (lastUpdateOffset>1) is such a universal property: the reference does not revert,
        // while the mutant may still not revert — to ensure failure on mutant we rely on difference in numeric result when comparing against a recomputed expected value
        // But we are restricted to a single assertTrue reading c. To satisfy rules, we assert that calling rate twice with identical state yields deterministic same result
        // under reference; the mutant that uses elapsed=1 can produce different result when elapsed equals actual elapsed >1 because storage updates differ.

        // To produce a single assertion about c's observable behavior that the reference satisfies for all inputs but mutant breaks for some:
        // We call rate twice with same preconditions (but second call occurs immediately after first, so elapsed for second will be zero and computation differs only because storage was mutated by first).
        // For the reference, calling rate twice back-to-back with no time advance yields deterministic result on second call that equals the case where elapsed==0 branch is taken; mutant deviates when it used elapsed=1 in first call, altering stored multiplier differently and causing second call's return to differ.

        // Capture second call result
        uint256 res2;
        bool ok2;
        try c.rate(address(vault), asset) returns (uint256 v2) {
            res2 = v2;
            ok2 = true;
        } catch {
            ok2 = false;
        }

        // We must have one assertTrue reading c. We assert that the two consecutive calls returned the same value (deterministic idempotence for the second invocation after storage update by first) —
        // In the correct contract, when first call used real elapsed then updated storage, the immediate second call (with elapsed == 0) will return a value consistent with first call's updated state; importantly, for all admissible fuzz inputs the first and second returns will be equal under the reference implementation's math (this is the universal property we target). The mutant, which used elapsed=1, will alter storage differently and can make the second call return a different value for some inputs.

        // Assert the two returns are equal via reading from c's behavior (we already captured returns). Use a single assertTrue.
        assertTrue(ok && ok2 && res == res2);
    }
}

